import type { Readable } from 'node:stream';

/**
 * Where binary files live. Local disk serves development and a single server;
 * Cloudflare R2 holds them when it's configured (see `storage.ts`).
 */
export interface ObjectStorage {
  readonly driver: 'local' | 'r2';
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  open(key: string): Promise<{ stream: Readable; size: number } | null>;
  remove(key: string): Promise<void>;
}

/** Keys are generated by the API ("<objectId>-thumb.webp"); anything else is refused. */
const SAFE_KEY = /^[a-z0-9][a-z0-9._-]{0,127}$/i;

export function assertKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error(`Unsafe storage key: ${key}`);
}

/** Keys never repeat (each upload gets a new id), so every copy can be cached for good. */
export const IMMUTABLE = 'public, max-age=31536000, immutable';
